    function setPlatformEdition(edition, save = true) {
      const mode = (edition === 'enterprise') ? 'enterprise' : 'clinic';
      state.platformEdition = mode;
      window.platformEdition = mode;
      if (save) {
        try {
          localStorage.setItem('zayvora_platform_edition', mode);
        } catch (e) {}
      }
      updateEditionUI(mode);

      // If switching to clinic mode while active role is an enterprise-only module, switch gracefully to doctor
      const enterpriseOnlyRoles = ['manufacturing', 'research', 'hardware', 'enterprise'];
      if (mode === 'clinic' && enterpriseOnlyRoles.includes(state.role)) {
        switchRole('doctor', true);
      } else {
        renderNavigation();
        renderWorkspace();
      }

      showNotification(
        mode === 'clinic'
          ? '🏥 ZAYVORA Clinic OS Active (Simplified for OPD, Patients & Dispensary)'
          : '🏛️ ZAYVORA Flagship HQ Active (Full Sovereign R&D, Manufacturing & Clinical Trials)',
        'success'
      );
    }

    function togglePlatformEditionFromModal() {
      const nextMode = (state.platformEdition === 'clinic') ? 'enterprise' : 'clinic';
      setPlatformEdition(nextMode, true);
    }

    function updateEditionUI(mode) {
      const activeMode = mode || state.platformEdition || 'clinic';
      const isClinic = (activeMode === 'clinic');

      // 1. Header Segmented Toggle Buttons
      const clinicBtn = document.getElementById('btn-edition-clinic');
      const enterpriseBtn = document.getElementById('btn-edition-enterprise');
      if (clinicBtn && enterpriseBtn) {
        if (isClinic) {
          clinicBtn.className = 'px-2.5 py-1 rounded-lg font-bold text-[11px] flex items-center gap-1.5 transition cursor-pointer bg-emerald-600 text-white shadow-sm ring-1 ring-emerald-400/40';
          enterpriseBtn.className = 'px-2.5 py-1 rounded-lg font-bold text-[11px] flex items-center gap-1.5 transition cursor-pointer text-slate-400 hover:text-white';
        } else {
          enterpriseBtn.className = 'px-2.5 py-1 rounded-lg font-bold text-[11px] flex items-center gap-1.5 transition cursor-pointer bg-amber-600 text-white shadow-sm ring-1 ring-amber-400/40';
          clinicBtn.className = 'px-2.5 py-1 rounded-lg font-bold text-[11px] flex items-center gap-1.5 transition cursor-pointer text-slate-400 hover:text-white';
        }
      }

      // 2. Header Brand Badge & Subtitle (Context-Aware: Public vs Clinical vs Enterprise)
      const badge = document.getElementById('header-edition-badge');
      const sub = document.getElementById('header-edition-sub');
      const isSuperAdmin = !!(state.currentUser && (state.currentUser.role === 'admin' || state.currentUser.role === 'super_admin' || state.currentUser.isSuperAdmin));
      const isPublic = (typeof state !== 'undefined' && state.role === 'website');

      if (badge) {
        if (isPublic) {
          badge.textContent = 'HEALTH OS™';
          badge.className = 'text-emerald-400 font-bold text-xs uppercase tracking-wider bg-emerald-950/60 border border-emerald-500/30 px-2 py-0.5 rounded-md';
        } else if (!isClinic && isSuperAdmin) {
          badge.textContent = 'ENTERPRISE HQ™';
          badge.className = 'text-amber-400 font-bold text-xs uppercase tracking-wider bg-amber-950/60 border border-amber-500/30 px-2 py-0.5 rounded-md';
        } else {
          badge.textContent = 'MATAB OS™';
          badge.className = 'text-emerald-400 font-bold text-xs uppercase tracking-wider bg-emerald-950/60 border border-emerald-500/30 px-2 py-0.5 rounded-md';
        }
      }
      if (sub) {
        if (isPublic) {
          sub.textContent = 'Integrative Healthcare & Classical Matab';
        } else if (!isClinic && isSuperAdmin) {
          sub.textContent = 'ZAYVORA Sovereign Health OS & R&D Cloud';
        } else {
          sub.textContent = 'Unani OPD & Clinical Practice Management';
        }
      }

      // 3. Role Selector Dropdown Options
      const roleSelect = document.getElementById('role-selector');
      if (roleSelect) {
        if (isClinic) {
          roleSelect.innerHTML = `
            <optgroup label="🩺 Clinical Care Desks" class="bg-[#0F172A] text-emerald-300 font-bold">
              <option value="doctor" ${state.role==='doctor'?'selected':''}>🩺 Doctor Desk</option>
              <option value="clinic" ${state.role==='clinic'?'selected':''}>📋 Reception (OPD Queue)</option>
              <option value="pharmacy" ${state.role==='pharmacy'?'selected':''}>💊 Pharmacy & Dispensary</option>
              <option value="nurse" ${state.role==='nurse'?'selected':''}>🏥 Nurse Station</option>
              <option value="patient" ${state.role==='patient'?'selected':''}>👤 Patient Portal</option>
            </optgroup>
          `;
        } else {
          roleSelect.innerHTML = `
            <optgroup label="👑 Super Admin & Governance" class="bg-[#0F172A] text-amber-300 font-bold">
              <option value="admin" ${state.role==='admin'?'selected':''}>🛡️ Admin Control</option>
              <option value="enterprise" ${state.role==='enterprise'?'selected':''}>🏛️ Executive HQ</option>
            </optgroup>
            <optgroup label="🩺 Clinical Care Desks" class="bg-[#0F172A] text-emerald-300 font-bold">
              <option value="doctor" ${state.role==='doctor'?'selected':''}>🩺 Doctor</option>
              <option value="nurse" ${state.role==='nurse'?'selected':''}>🏥 Nurse</option>
              <option value="clinic" ${state.role==='clinic'?'selected':''}>📋 Reception</option>
              <option value="patient" ${state.role==='patient'?'selected':''}>👤 Patient</option>
            </optgroup>
            <optgroup label="💊 Pharmacy & Production" class="bg-[#0F172A] text-cyan-300 font-bold">
              <option value="pharmacy" ${state.role==='pharmacy'?'selected':''}>💊 Pharmacy</option>
              <option value="manufacturing" ${state.role==='manufacturing'?'selected':''}>🏭 Manufacturing</option>
              <option value="hardware" ${state.role==='hardware'?'selected':''}>📡 IoMT</option>
            </optgroup>
            <optgroup label="🔬 Research" class="bg-[#0F172A] text-purple-300 font-bold">
              <option value="research" ${state.role==='research'?'selected':''}>🔬 Research</option>
            </optgroup>
          `;
        }
      }

      // 4. Login Modal UI
      const modalTitle = document.getElementById('login-modal-edition-title');
      const modalDesc = document.getElementById('login-modal-edition-desc');
      const modalIcon = document.getElementById('login-modal-edition-icon');
      const modalToggleBtn = document.getElementById('login-modal-edition-toggle-btn');
      if (modalTitle && modalDesc) {
        if (isClinic) {
          modalTitle.textContent = 'ZAYVORA Clinic Edition';
          modalDesc.textContent = 'Simplified for Daily OPD, Patients & Dispensary';
          if (modalIcon) modalIcon.textContent = '🏥';
          if (modalToggleBtn) modalToggleBtn.textContent = 'Switch to Flagship HQ 🏛️';
        } else {
          modalTitle.textContent = 'ZAYVORA Flagship Enterprise HQ';
          modalDesc.textContent = 'Full Sovereign R&D, Manufacturing & Clinical Trials';
          if (modalIcon) modalIcon.textContent = '🏛️';
          if (modalToggleBtn) modalToggleBtn.textContent = 'Switch to Clinic OS 🏥';
        }
      }

      // 5. Quick Role Cards Visibility in Modal
      const enterpriseCards = document.querySelectorAll('.quick-role-enterprise');
      enterpriseCards.forEach(card => {
        if (isClinic) {
          card.classList.add('hidden');
        } else {
          card.classList.remove('hidden');
        }
      });
      const enterpriseNotice = document.getElementById('login-enterprise-notice');
      if (enterpriseNotice) {
        const isSuperAdmin = !!(state.currentUser && (state.currentUser.isSuperAdmin || state.currentUser.role === 'admin'));
        if (!isClinic && isSuperAdmin) {
          enterpriseNotice.classList.remove('hidden');
        } else {
          enterpriseNotice.classList.add('hidden');
        }
      }
    }

    window.setPlatformEdition = setPlatformEdition;
    window.togglePlatformEditionFromModal = togglePlatformEditionFromModal;
    window.updateEditionUI = updateEditionUI;
    window.getDoctorNavItems = getDoctorNavItems;

    function scrollToOpdBooking() {
      const card = document.getElementById('opd-booking-card');
      if (card) {
        card.scrollIntoView({ behavior: 'smooth' });
      } else {
        if (typeof viewWebsitePage === 'function') viewWebsitePage('home');
        setTimeout(() => {
          document.getElementById('opd-booking-card')?.scrollIntoView({ behavior: 'smooth' });
        }, 120);
      }
    }

    function closeVisualMizajCard() {
      const modal = document.getElementById('visual-mizaj-card-modal');
      if (modal) modal.classList.add('hidden');
    }

    window.scrollToOpdBooking = scrollToOpdBooking;
    window.closeVisualMizajCard = closeVisualMizajCard;

    (function initializePlatformEdition() {
      let saved = null;
      try { saved = localStorage.getItem('zayvora_platform_edition'); } catch (e) {}
      const activeEdition = saved || 'clinic';
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => updateEditionUI(activeEdition));
      } else {
        updateEditionUI(activeEdition);
      }
    })();


    function switchRole(newRole, bypassAuth = false) {
      if (typeof window !== 'undefined') window.switchRole = switchRole;

      const protectedRoles = ['doctor', 'pharmacy', 'clinic', 'nurse', 'admin', 'manufacturing', 'research', 'patient', 'enterprise', 'hardware', 'mobile'];
      const isSuperAdmin = state.currentUser && (state.currentUser.role === 'admin' || state.currentUser.role === 'super_admin' || state.currentUser.isSuperAdmin);

      // Security Gate: Protect all clinical & administrative consoles
      if (protectedRoles.includes(newRole) && !isSuperAdmin && !bypassAuth) {
        const hasSession = state.currentUser && (state.currentUser.role === newRole || (newRole === 'patient' && state.currentUser.role === 'patient'));
        if (!hasSession) {
          toggleLoginModal(true);
          prefillLogin(newRole);
          showNotification(`Please enter password and click 'Sign In' to access ${newRole.toUpperCase()} desk.`, 'info');
          return;
        }
      }

      if (newRole !== 'website' && newRole !== 'herbals') {
        const roleProfiles = {
          doctor: { name: 'Hakeem Dr. Irfan Ashraf', title: 'Senior Tabeeb & Lead Clinician (BUMS - AKTC AMU)', email: 'dr.irfan@zayvorahealth.com' },
          clinic: { name: 'Reception & Patient Intake Desk', title: 'OPD Queue & Token In-Charge', email: 'reception@zayvorahealth.com' },
          nurse: { name: 'Inpatient Nursing Station', title: 'Ward 2A Triage In-Charge', email: 'nurse@zayvorahealth.com' },
          patient: { name: 'Hamza Farooqi', title: 'Patient (MRN-2026-0814) • Verified Record', email: 'patient.hamza@zayvorahealth.com' },
          pharmacy: { name: 'Chief Pharmacist', title: 'Clinical Pharmacy & FEFO In-Charge', email: 'pharmacy@zayvorahealth.com' },
          manufacturing: { name: 'Head of Botanical QA/QC', title: 'eBMR Batch Release Officer', email: 'manufacturing@zayvorahealth.com' },
          admin: { name: 'Enterprise Super Administrator', title: 'Platform Security & Governance', email: 'admin@zayvorahealth.com' },
          research: { name: 'Principal Clinical Investigator', title: 'RWE & Pharmacopoeia Editorial Board', email: 'research@zayvorahealth.com' },
          enterprise: { name: 'Hakeem Dr. Irfan Ashraf', title: 'Founder & Chairman', email: 'dr.irfan@zayvorahealth.com' },
          hardware: { name: 'IoMT Hardware Gateway', title: 'Hardware Admin', email: 'hardware@zayvorahealth.com' },
          herbals: { name: 'Retail Guest', title: 'Herbal Store Customer', email: 'guest@zayvorahealth.com' },
          mobile: { name: 'Mobile Bedside User', title: 'PWA Bedside User', email: 'mobile@zayvorahealth.com' }
        };
        const p = roleProfiles[newRole] || { name: 'Authorized User', title: newRole.toUpperCase(), email: `${newRole}@zayvorahealth.com` };
        
        // If Super Admin is switching between desks, preserve Super Admin status!
        if (isSuperAdmin) {
          state.currentUser.activeDesk = newRole;
          state.currentUser.title = `Super Admin Oversight • ${newRole.toUpperCase()} Desk`;
        } else if (state.currentUser && state.currentUser.token) {
          state.currentUser.role = newRole;
        } else if (bypassAuth) {
          const secureToken = 'zyv.' + btoa(JSON.stringify({ uid: 'USR-' + newRole.toUpperCase(), email: p.email, name: p.name, role: newRole, exp: Math.floor(Date.now() / 1000) + 86400 })) + '.sig';
          state.currentUser = { email: p.email, name: p.name, title: p.title, role: newRole, isSuperAdmin: (newRole === 'admin'), token: secureToken };
        }
      }
      state.role = newRole;
      state.tab = (roleNavs[newRole] && roleNavs[newRole][0]) ? roleNavs[newRole][0].id : 'overview';
      try { sessionStorage.setItem('zayvora_session_desk', newRole); } catch(e) {}
      const sel = document.getElementById('role-selector');
      if (sel) sel.value = newRole;
      updateAuthHeaderUI();
      renderNavigation();
      renderWorkspace();
      try { window.scrollTo({ top: 0, behavior: 'smooth' }); } catch(e) {}
    }

    function navigateToV2Hub(hub) {
      const hubMap = {
        command_center: { role: 'doctor', tab: 'today' },
        patients: { role: 'doctor', tab: 'patients' },
        clinical: { role: 'doctor', tab: 'consultation' },
        zmie: { role: 'doctor', tab: 'knowledge' },
        pharmacy: { role: 'pharmacy', tab: 'dispensing' },
        formulation: { role: 'research', tab: 'zfie_studio' },
        outcomes: { role: 'research', tab: 'outcomes' },
        research: { role: 'research', tab: 'studies' },
        admin: { role: 'admin', tab: 'audit' }
      };

      // Security Gate: Gatekeep internal hubs. Must be authenticated!
      if (!state.currentUser || !state.currentUser.token) {
        toggleLoginModal(true);
        const targetRole = hubMap[hub] ? hubMap[hub].role : 'doctor';
        prefillLogin(targetRole);
        showNotification('Please sign in with your staff credentials to access this clinical module.', 'info');
        return;
      }

      const target = hubMap[hub] || { role: 'doctor', tab: 'today' };
      switchRole(target.role, false);
      switchTab(target.tab);

      // Highlight active V2 master hub pill
      document.querySelectorAll('.v2-hub-btn').forEach(btn => {
        btn.classList.remove('text-emerald-300', 'bg-emerald-500/10', 'border-emerald-500/30');
        btn.classList.add('text-slate-400');
      });
      const activeBtn = document.getElementById(`hub-btn-${hub}`);
      if (activeBtn) {
        activeBtn.classList.remove('text-slate-400');
        activeBtn.classList.add('text-emerald-300', 'bg-emerald-500/10', 'border-emerald-500/30');
      }
    }
    window.navigateToV2Hub = navigateToV2Hub;

    function switchTab(newTab) {
      if (typeof window !== 'undefined') window.switchTab = switchTab;

      state.tab = newTab;
      if (state.role === 'website') {
        try {
          if (window.history && window.history.pushState) {
            window.history.pushState(null, null, '#' + newTab);
          } else {
            window.location.hash = newTab;
          }
        } catch (e) {}
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        // Keep header and top bar comfortably in view on tab switch
      }
      renderNavigation();
      renderWorkspace();
    }

    function isTabActive(itemId, currentTab) {
      if (itemId === currentTab) return true;
      if (state.role === 'website') {
        if (itemId === 'doctors' && (currentTab === 'doctors' || currentTab === 'team')) return true;
        if (itemId === 'careers' && currentTab === 'careers') return true;
        if (itemId === 'ethics' && currentTab === 'ethics') return true;
        if (itemId === 'services' && (currentTab.startsWith('services_') || currentTab === 'care_journey' || currentTab === 'clinics')) return true;
        if (itemId === 'products' && (currentTab.startsWith('products_') || currentTab === 'shipping_refunds')) return true;
        if (itemId === 'knowledge' && currentTab === 'knowledge') return true;
        if (itemId === 'research' && currentTab.startsWith('research_')) return true;
        if (itemId === 'about' && (currentTab === 'philosophy' || currentTab === 'privacy' || currentTab === 'terms' || currentTab === 'disclaimer' || currentTab === 'refunds' || currentTab === 'shipping' || currentTab === 'grievance')) return true;
        if (itemId === 'contact' && currentTab === 'faqs') return true;
      }
      return false;
    }

    function selectDoctorDesk(tabId) {
      if (typeof toggleDoctorNavDropdown === 'function') {
        toggleDoctorNavDropdown(null, false);
      }
      if (typeof switchTab === 'function') {
        switchTab(tabId);
      }
    }
    window.selectDoctorDesk = selectDoctorDesk;

    function populateDoctorNavDropdownMenu() {
      let menu = document.getElementById('doctor-more-nav-menu');
      if (!menu) {
        menu = document.createElement('div');
        menu.id = 'doctor-more-nav-menu';
        menu.className = 'hidden fixed rounded-2xl bg-[#0F172A] border border-slate-700 shadow-2xl p-2.5 space-y-1 z-[999999] backdrop-blur-xl';
        document.body.appendChild(menu);
      }
      const allItems = (typeof getDoctorNavItems === 'function') ? getDoctorNavItems() : [];
      const primaryIds = ['today', 'consultation', 'patients', 'prescriptions'];
      const secondaryItems = allItems.filter(item => !primaryIds.includes(item.id));
      if (secondaryItems.length === 0) {
        menu.innerHTML = '<div class="p-3 text-xs text-slate-400 text-center">No additional specialty desks configured.</div>';
        return;
      }
      menu.innerHTML = `
        <div class="dropdown-header px-3 py-2 border-b border-slate-800 text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center justify-between">
          <span>Specialty Desks</span>
          <span class="badge text-emerald-400 font-mono text-[11px] font-semibold">${secondaryItems.length} Desks</span>
        </div>
        <div class="py-1 space-y-1">
          ${secondaryItems.map(item => `
            <button type="button" onclick="selectDoctorDesk('${item.id}')" class="desk-item w-full text-left px-3 py-2 rounded-xl text-xs font-medium ${isTabActive(item.id, state.tab) ? 'active-item bg-emerald-600 text-white font-bold shadow' : 'text-slate-300 hover:bg-slate-800 hover:text-white'} flex items-center justify-between transition cursor-pointer group">
              <span class="flex items-center gap-2">${item.label}</span>
              <span class="text-[10px] text-slate-400 group-hover:text-emerald-400 font-mono">→</span>
            </button>
          `).join('')}
        </div>
      `;
    }
    window.populateDoctorNavDropdownMenu = populateDoctorNavDropdownMenu;

    function toggleDoctorNavDropdown(e, forceState) {
      if (e) {
        if (typeof e.stopPropagation === 'function') e.stopPropagation();
        if (typeof e.preventDefault === 'function') e.preventDefault();
      }
      const btn = document.getElementById('doctor-more-nav-btn');
      let menu = document.getElementById('doctor-more-nav-menu');
      if (!btn) return;

      if (!menu) {
        menu = document.createElement('div');
        menu.id = 'doctor-more-nav-menu';
        menu.className = 'hidden fixed rounded-2xl bg-[#0F172A] border border-slate-700 shadow-2xl p-2.5 space-y-1 z-[999999] backdrop-blur-xl';
        document.body.appendChild(menu);
      } else if (menu.parentElement !== document.body) {
        document.body.appendChild(menu);
      }

      const isCurrentlyHidden = menu.classList.contains('hidden') || menu.style.display === 'none';
      const shouldOpen = (typeof forceState === 'boolean') ? forceState : isCurrentlyHidden;
      const arrow = document.getElementById('doctor-more-nav-arrow');

      if (shouldOpen) {
        populateDoctorNavDropdownMenu();
        const rect = btn.getBoundingClientRect();
        const menuWidth = Math.min(300, window.innerWidth - 20);

        menu.style.position = 'fixed';
        menu.style.top = (rect.bottom + 8) + 'px';

        let targetLeft = rect.left;
        if (targetLeft + menuWidth > window.innerWidth - 10) {
          targetLeft = window.innerWidth - menuWidth - 10;
        }
        if (targetLeft < 10) targetLeft = 10;

        menu.style.left = targetLeft + 'px';
        menu.style.width = menuWidth + 'px';
        menu.style.maxWidth = 'calc(100vw - 20px)';
        menu.style.zIndex = '999999';
        menu.classList.remove('hidden');
        menu.style.display = 'block';

        if (arrow) arrow.style.transform = 'rotate(180deg)';
      } else {
        menu.classList.add('hidden');
        menu.style.display = 'none';
        if (arrow) arrow.style.transform = 'rotate(0deg)';
      }
    }
    window.toggleDoctorNavDropdown = toggleDoctorNavDropdown;

    if (typeof document !== 'undefined') {
      document.addEventListener('click', (e) => {
        const menu = document.getElementById('doctor-more-nav-menu');
        const btn = document.getElementById('doctor-more-nav-btn');
        if (menu && (!menu.classList.contains('hidden') && menu.style.display !== 'none')) {
          if (btn && (btn === e.target || btn.contains(e.target))) return;
          if (menu.contains(e.target)) return;
          toggleDoctorNavDropdown(null, false);
        }
      });
      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          const menu = document.getElementById('doctor-more-nav-menu');
          if (menu && (!menu.classList.contains('hidden') && menu.style.display !== 'none')) {
            toggleDoctorNavDropdown(null, false);
          }
        }
      });
      window.addEventListener('resize', () => {
        const menu = document.getElementById('doctor-more-nav-menu');
        const btn = document.getElementById('doctor-more-nav-btn');
        if (menu && (!menu.classList.contains('hidden') && menu.style.display !== 'none') && btn) {
          const rect = btn.getBoundingClientRect();
          const menuWidth = Math.min(300, window.innerWidth - 20);
          let targetLeft = rect.left;
          if (targetLeft + menuWidth > window.innerWidth - 10) {
            targetLeft = window.innerWidth - menuWidth - 10;
          }
          if (targetLeft < 10) targetLeft = 10;
          menu.style.top = (rect.bottom + 8) + 'px';
          menu.style.left = targetLeft + 'px';
        }
      }, { passive: true });
    }

    function renderNavigation() {
      const navContainer = document.getElementById('role-navigation');
      if (!navContainer) return;

      if (state.role === 'doctor') {
        const allItems = getDoctorNavItems();
        const primaryIds = ['today', 'consultation', 'patients', 'prescriptions'];
        const primaryItems = [];
        const secondaryItems = [];

        allItems.forEach(item => {
          if (primaryIds.includes(item.id)) {
            primaryItems.push(item);
          } else {
            secondaryItems.push(item);
          }
        });

        // Ensure logical order: today, consultation, patients, prescriptions
        primaryItems.sort((a, b) => primaryIds.indexOf(a.id) - primaryIds.indexOf(b.id));

        const isSecondaryActive = secondaryItems.some(item => isTabActive(item.id, state.tab));
        const activeSecondaryItem = secondaryItems.find(item => isTabActive(item.id, state.tab));
        const cleanSecondaryLabel = activeSecondaryItem ? activeSecondaryItem.label.replace(/<[^>]+>/g, '').trim() : '';
        const dropdownLabel = isSecondaryActive && cleanSecondaryLabel
          ? `📚 ${cleanSecondaryLabel} ▾`
          : '📚 Clinical Tools & Specialty Desks ▾';

        let html = primaryItems.map(item => `
          <button onclick="switchTab('${item.id}')" class="nav-link shrink-0 ${isTabActive(item.id, state.tab) ? 'active' : 'text-[var(--muted)] hover:text-white'} px-3.5 py-1.5 rounded-xl text-xs font-semibold border border-transparent transition-colors">
            ${item.label}
          </button>
        `).join('');

        if (secondaryItems.length > 0) {
          html += `
            <div class="relative inline-block text-left shrink-0" id="doctor-more-nav-dropdown-wrap">
              <button id="doctor-more-nav-btn" type="button" onclick="toggleDoctorNavDropdown(event)" class="nav-link shrink-0 ${isSecondaryActive ? 'active' : 'text-[var(--muted)] hover:text-white'} px-3.5 py-1.5 rounded-xl text-xs font-semibold border border-transparent transition-colors flex items-center gap-1.5 bg-slate-900/60 hover:bg-slate-800 cursor-pointer" title="Click to open Specialty Desks">
                <span>${dropdownLabel}</span>
                <span id="doctor-more-nav-arrow" class="inline-block transition-transform duration-200">▾</span>
              </button>
            </div>
          `;
          // Pre-populate detached floating menu in body
          try { populateDoctorNavDropdownMenu(); } catch (err) {}
        }

        navContainer.innerHTML = html;
        return;
      }

      const navItems = roleNavs[state.role] || [];
      let html = navItems.map(item => `
        <button onclick="switchTab('${item.id}')" class="nav-link shrink-0 ${isTabActive(item.id, state.tab) ? 'active' : 'text-[var(--muted)] hover:text-white'} px-3.5 py-1.5 rounded-xl text-xs font-medium border border-transparent transition-colors">
          ${item.label}
        </button>
      `).join('');

      if (state.role === 'website') {
        html += `
          <button onclick="document.getElementById('site-footer-directory')?.scrollIntoView({ behavior: 'smooth' })" class="shrink-0 text-xs text-slate-400 hover:text-emerald-400 px-3 py-1.5 rounded-xl border border-dashed border-slate-700/80 hover:border-emerald-500/50 flex items-center gap-1.5 transition ml-auto" title="Explore all 25 canonical pages & complete sitemap in footer">
            <span>Sitemap &amp; Directory ↓</span>
          </button>
        `;
      }
      navContainer.innerHTML = html;
    }

    function showNotification(text, type = 'success') {
      const banner = document.getElementById('system-notification');
      const textEl = document.getElementById('system-notif-text');
      const iconEl = document.getElementById('system-notif-icon');

      textEl.textContent = text;
      if (type === 'success') {
        banner.className = "p-4 rounded-xl border text-xs flex items-center justify-between bg-emerald-500/10 border-emerald-500/30 text-emerald-300";
        iconEl.textContent = "✓";
      } else if (type === 'error') {
        banner.className = "p-4 rounded-xl border text-xs flex items-center justify-between bg-rose-500/10 border-rose-500/30 text-rose-300";
        iconEl.textContent = "✕";
      } else {
        banner.className = "p-4 rounded-xl border text-xs flex items-center justify-between bg-blue-500/10 border-blue-500/30 text-blue-300";
        iconEl.textContent = "ℹ";
      }
      banner.classList.remove('hidden');
      setTimeout(() => banner.classList.add('hidden'), 5000);
    }

    function dismissNotification() {
      document.getElementById('system-notification').classList.add('hidden');
    }

    function toggleHelpModal() {
      const el = document.getElementById('help-modal');
      if (el) {
        el.classList.toggle('hidden');
        if (el.classList.contains('hidden') && typeof window.ensureScrollable === 'function') {
          window.ensureScrollable();
        }
      }
    }

    // =========================================================================
    // WORKSPACE RENDERERS
    // =========================================================================
    function renderWorkspace() {
      const main = document.getElementById('workspace-container');
      if (!main) {
        if (document.readyState === 'loading') {
          document.addEventListener('DOMContentLoaded', renderWorkspace, { once: true });
        } else {
          setTimeout(renderWorkspace, 60);
        }
        return;
      }

      try {
        if (state.role === 'patient') {
          renderPatientApp(main);
        } else if (state.role === 'doctor') {
          const validDoctorTabs = ['today', 'consultation', 'patients', 'prescriptions', 'followups', 'assistant', 'knowledge', 'tadbeer', 'nafsiyat', 'ghiza', 'yad', 'profile'];
          if (!state.tab || !validDoctorTabs.includes(state.tab)) {
            state.tab = 'today';
          }
          renderDoctorApp(main);
        } else if (state.role === 'clinic') {
          renderClinicApp(main);
        } else if (state.role === 'nurse') {
          renderNurseApp(main);
        } else if (state.role === 'pharmacy') {
          renderPharmacyApp(main);
        } else if (state.role === 'research') {
          renderResearchApp(main);
        } else if (state.role === 'admin') {
          renderAdminApp(main);
        } else if (state.role === 'enterprise') {
          renderEnterpriseApp(main);
        } else if (state.role === 'manufacturing') {
          renderManufacturingApp(main);
        } else if (state.role === 'website') {
          renderWebsiteApp(main);
        } else if (state.role === 'herbals') {
          renderHerbalsApp(main);
        } else if (state.role === 'mobile') {
          renderMobileApp(main);
        } else if (state.role === 'hardware') {
          renderHardwareApp(main);
        } else {
          state.role = 'website';
          state.tab = 'home';
          renderWebsiteApp(main);
        }
      } catch (renderError) {
        console.error('[ZAYVORA Self-Healing Engine] Intercepted workspace render error:', renderError);
        main.innerHTML = `
          <div class="min-h-[50vh] flex items-center justify-center p-6">
            <div class="max-w-md w-full p-8 rounded-3xl bg-slate-900 border border-emerald-500/40 text-center shadow-2xl space-y-4">
              <div class="w-14 h-14 mx-auto rounded-2xl bg-emerald-500/20 border border-emerald-500/40 flex items-center justify-center text-3xl">🌿</div>
              <h3 class="text-base font-bold text-white">ZAYVORA Workspace Shielded</h3>
              <p class="text-xs text-slate-300 leading-relaxed">The clinical workspace safely intercepted a transient view exception without interrupting session security.</p>
              <div class="pt-2 flex flex-col gap-2">
                <button onclick="state.role='website'; state.tab='home'; renderWorkspace();" class="w-full py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs shadow-lg transition">
                  Return to Home Overview →
                </button>
                <button onclick="window.location.reload();" class="w-full py-2 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-300 font-semibold text-xs border border-slate-700 transition">
                  Reload Clinical Workspace
                </button>
              </div>
            </div>
          </div>
        `;
      }

      if (typeof window.ensureScrollable === 'function') {
        window.ensureScrollable();
      }
    }

