    async function loadClinicAppointmentsDynamicTable() {
      const tbody = document.getElementById('clinic-appointments-table-body');
      if (!tbody) return;

      let list = [];
      try {
        const res = await apiFetch('/api/v1/appointments');
        if (res.ok) {
          const data = await res.json();
          if (data.appointments && data.appointments.length > 0) {
            list = data.appointments;
          }
        }
      } catch (err) {
        console.warn('[ZAYVORA] Live appointments fetch error:', err);
      }

      // If state.appointments has any newly registered session appointments, combine them
      if (state.appointments && state.appointments.length > 0 && list.length === 0) {
        list = state.appointments.map(a => ({
          appointment_time: a.scheduledTime || 'Today, OPD Queue',
          patient_name: a.patientName || 'Patient',
          mrn: a.mrn || 'MRN-LIVE',
          doctor_name: a.doctorName || 'Hakeem Dr. Irfan Ashraf',
          room: 'Room 204',
          status: a.status || 'Waiting',
          token_number: a.token || 'T-101'
        }));
      }

      if (list.length > 0) {
        tbody.innerHTML = list.map(a => {
          const aTime = a.appointment_time || '10:00 AM';
          const aName = a.patient_name || a.patientName || 'Patient';
          const aMrn = a.mrn || 'MRN-LIVE';
          const aDoc = a.doctor_name || a.doctorName || 'Hakeem Dr. Irfan Ashraf';
          const aRoom = a.room || 'Room 204';
          const aStatus = a.status || 'Checked In';
          const aToken = a.token_number || a.token || 'T-101';
          return `
            <tr class="hover:bg-slate-800/40 transition">
              <td class="p-3 font-mono font-bold text-white">${aTime}</td>
              <td class="p-3 font-bold text-white">${aName}</td>
              <td class="p-3 font-mono text-[11px]">${aMrn}</td>
              <td class="p-3">${aDoc}</td>
              <td class="p-3">${aRoom}</td>
              <td class="p-3"><span class="badge-emerald text-[9px] px-2 py-0.5 rounded font-bold">${aStatus}</span></td>
              <td class="p-3 text-right">
                <div class="flex items-center justify-end gap-1.5">
                  <button onclick="sendTokenViaWhatsApp('${aToken}', '${aName.replace(/'/g, "\\'")}', '+91 97738 82657')" class="px-2.5 py-1 bg-emerald-700/80 hover:bg-emerald-600 text-white font-bold rounded-lg text-xs flex items-center gap-1 transition" title="Send Token via WhatsApp">
                    <span>📲</span> WhatsApp
                  </button>
                  <button onclick="handleNotifyPatientAppointment(this)" class="px-2.5 py-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-bold rounded-lg text-xs">SMS</button>
                </div>
              </td>
            </tr>
          `;
        }).join('');
        return;
      }

      // Evaluation case loader for testing & demonstration
      if (window._loadSampleClinicAppointments) {
        tbody.innerHTML = `
          <tr>
            <td class="p-3">10:30 AM</td>
            <td class="p-3">Hamza Farooqi</td>
            <td class="p-3">MRN-2026-0814</td>
            <td class="p-3">Hakeem Dr. Irfan Ashraf</td>
            <td class="p-3">Room 204</td>
            <td class="p-3"><span class="badge-blue text-[9px] px-2 py-0.5 rounded font-bold">Checked In</span></td>
            <td class="p-3 text-right">
              <button onclick="sendTokenViaWhatsApp('A-12', 'Hamza Farooqi', '+91 97738 82657')" class="px-2.5 py-1 bg-emerald-700/80 hover:bg-emerald-600 text-white font-bold rounded-lg text-xs flex items-center gap-1 transition" title="Send Token via WhatsApp">
                <span>📲</span> WhatsApp
              </button>
            </td>
          </tr>
        `;
        return;
      }

      // Clean Slate Active state
      tbody.innerHTML = `
        <tr>
          <td colspan="7" class="p-8 text-center text-slate-400">
            <div class="max-w-md mx-auto space-y-2">
              <span class="text-3xl block">📅</span>
              <strong class="text-white text-sm block">Live Production Clean Slate: No Active Appointments</strong>
              <p class="text-xs text-slate-400">Queue is currently clear. Register a walk-in patient to allocate an instant OPD token.</p>
              <div class="pt-2 flex justify-center gap-2">
                <button onclick="openAddPatientModal()" class="px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs shadow">
                  + Register Walk-In
                </button>
              </div>
            </div>
          </td>
        </tr>
      `;
    }

    function filterClinicPatients(q) {
      const term = (q || '').toLowerCase().trim();
      const tbody = document.getElementById('clinic-patients-table-body');
      if (!tbody) return;
      const rows = tbody.querySelectorAll('tr');
      rows.forEach(r => {
        if (!term) {
          r.style.display = '';
          return;
        }
        const text = r.textContent.toLowerCase();
        r.style.display = text.includes(term) ? '' : 'none';
      });
    }

