  function openBilingualPrescriptionSlipModal() {
    const m = document.getElementById('bilingual-rx-slip-modal');
    if (!m) return;

    // Apply custom clinic letterhead settings
    const letterheadCfg = getClinicLetterheadSettings();
    applyLetterheadToPrescriptionSlip(letterheadCfg);

    const pat = state.patient || { name: 'Patient', age: 45, gender: 'Male', mrn: 'MRN-2026-LIVE', mizaj: 'Damawi' };
    const safeSetText = (id, val) => {
      const el = document.getElementById(id);
      if (el) el.innerText = val || '';
    };

    safeSetText('slip-patient-name', pat.name);
    safeSetText('slip-patient-demo', `${pat.age || 45} Y / ${pat.gender || 'Male'} (${(pat.gender || '').toLowerCase() === 'female' ? 'عورت' : 'مرد'})`);
    safeSetText('slip-patient-mrn', pat.mrn || 'MRN-2026-LIVE');
    safeSetText('slip-patient-mizaj', `${pat.mizaj || 'Balanced'} (مزاج)`);
    
    const diagInput = document.getElementById('fast-diagnosis-input');
    if (diagInput && diagInput.value) {
      safeSetText('slip-patient-diagnosis', diagInput.value);
    }

    const parhezInput = document.getElementById('fast-parhez-text');
    if (parhezInput && parhezInput.value) {
      safeSetText('slip-forbidden-foods', parhezInput.value);
    }

    // Populate medicines table
    const tableBody = document.getElementById('slip-medicines-table-body');
    if (tableBody) {
      const rx = (state.prescriptions && state.prescriptions[0]) || {};
      const meds = rx.medicines || [];

      if (meds.length === 0) {
        tableBody.innerHTML = `
          <tr>
            <td colspan="6" class="p-4 text-center text-slate-400">No active medicines in prescription.</td>
          </tr>
        `;
      } else {
        tableBody.innerHTML = meds.map((m, idx) => {
          const formText = m.form ? `<span class="text-[11px] text-slate-600 font-medium">${m.form}${m.strength ? ' • ' + m.strength : ''}</span>` : (m.strength ? `<span class="text-[11px] text-slate-600 font-medium">${m.strength}</span>` : '');
          const cleanNotes = (m.notes && !m.notes.includes('CDS:') && !m.notes.includes('Integrative') && !m.notes.includes('Compound Twin')) ? m.notes : '';
          return `
          <tr class="hover:bg-slate-50 transition border-b border-slate-200">
            <td class="p-2.5 font-bold font-mono text-center border-r border-slate-200 text-slate-700">${idx + 1}</td>
            <td class="p-2.5 border-r border-slate-200">
              <strong class="text-slate-900 block text-xs font-bold">${m.name}</strong>
              ${formText}
              ${m.ingredients ? `<div class="mt-1 p-1.5 rounded bg-purple-50 border border-purple-200 text-[10px] text-purple-900 font-mono leading-relaxed"><strong>اجزاء (Constituents):</strong> ${m.ingredients}</div>` : ''}
            </td>
            <td class="p-2.5 text-center border-r border-slate-200 font-semibold text-emerald-800">
              ${m.morning && m.morning !== '—' ? `<span class="bg-amber-100 text-amber-900 px-2 py-0.5 rounded text-[10px] font-bold">☀️ ${m.morning}</span>` : '—'}
            </td>
            <td class="p-2.5 text-center border-r border-slate-200 font-semibold text-emerald-800">
              ${m.noon && m.noon !== '—' ? `<span class="bg-blue-100 text-blue-900 px-2 py-0.5 rounded text-[10px] font-bold">⛅ ${m.noon}</span>` : '—'}
            </td>
            <td class="p-2.5 text-center border-r border-slate-200 font-semibold text-emerald-800">
              ${m.night && m.night !== '—' ? `<span class="bg-indigo-100 text-indigo-900 px-2 py-0.5 rounded text-[10px] font-bold">🌙 ${m.night}</span>` : '—'}
            </td>
            <td class="p-2.5 text-slate-700 text-[11px]">
              <span class="font-bold text-emerald-900">${m.anupan || 'Neem garam paani (Warm water)'}</span>
              ${cleanNotes ? `<span class="block text-[10px] text-slate-500 mt-0.5">${cleanNotes}</span>` : ''}
            </td>
          </tr>
        `;
        }).join('');
      }
    }

    // SHA-256 Hash display
    safeSetText('slip-sha256-hash', 'sha256:' + Math.random().toString(16).substring(2, 10) + '... (Tamper-Evident Validated)');

    m.classList.remove('hidden');
  }

