  function getClinicLetterheadSettings() {
    const defaults = {
      clinicName: 'ZAYVORA INTEGRATIVE CLINICAL MATAB',
      clinicUrdu: 'مطب زیورا فار ہربل میڈیسن والطب یونانی',
      doctorName: 'Hakeem Dr. Irfan Ashraf',
      doctorDegree: 'BUMS (AKTC Aligarh Muslim University, Batch 2002, Passed 2007) • Senior Integrative Physician',
      doctorReg: 'BUMS/AMU/2007',
      clinicTiming: 'OPD Timing: 10:00 AM - 02:00 PM',
      clinicAddress: 'ZAYVORA Integrative Healthcare & Research Centre • Facility ID: ZAY-HQ-01'
    };
    try {
      const raw = localStorage.getItem('zayvora_clinic_letterhead_settings');
      if (raw) {
        return Object.assign({}, defaults, JSON.parse(raw));
      }
    } catch (e) {}
    return defaults;
  }

