  function applyBadalSubstitute(oldName, newName) {
    const rx = state.prescriptions && state.prescriptions[0];
    if (rx && rx.medicines) {
      const idx = rx.medicines.findIndex(m => m.name === oldName || m.name.includes(oldName));
      if (idx !== -1) {
        rx.medicines[idx].name = newName;
        rx.medicines[idx].notes = `Badal-e-Adwiyah applied: Replaced ${oldName} (Qarabadeen Canonical)`;
      }
    }
    closeBadalModal();
    // Compute Unani principles: Mizaj, 10-Ajnas Pulse, 12-Organ Axis, ICD-11 & Af'aal Cascade
    const unaniData = calculateAutonomousUnaniPrinciples(narrative, detectedDiag);
    renderUnaniPrinciplesSynthesis(unaniData);

    renderFastMatabPrescriptionList();
    calculateIlajBilZidd();
    autoSaveConsultationDraft();
    if (typeof showNotification === 'function') {
      showNotification(`✓ Replaced with canonical Badal: ${newName}`, 'success');
    }
  }

