  function sendFollowupReminderViaWhatsApp(patientId) {
    const pat = state.patient || { name: 'Patient', phone: '+91-9876543210' };
    const doc = getClinicLetterheadSettings();
    const d = new Date();
    d.setDate(d.getDate() + 14);
    const dateFormatted = d.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

    let text = `*🌿 ${doc.clinicName}*%0A`;
    text += `*FOLLOW-UP CONSULTATION APPOINTMENT REMINDER*%0A%0A`;
    text += `Salam *${pat.name}*!%0A`;
    text += `This is a courtesy reminder for your upcoming 14-day clinical follow-up appointment with *${doc.doctorName}*.%0A%0A`;
    text += `📅 *Scheduled Date:* ${dateFormatted}%0A`;
    text += `⏰ *Consultation Hours:* ${doc.clinicTiming}%0A`;
    text += `🏥 *Venue:* ${doc.clinicAddress}%0A%0A`;
    text += `*Important Instructions:*%0A`;
    text += `1. Please bring your previous prescription slip and any newly completed diagnostic lab reports.%0A`;
    text += `2. Continue your prescribed dietary restrictions (Parhez) and medicines as advised.%0A%0A`;
    text += `_For appointments or queries, reply directly to this WhatsApp message._%0A`;
    text += `_Digital Care Portal • 21 CFR Part 11 Validated (ZAYVORA Health OS)_`;

    let cleanPhone = (pat.phone || '+91-9876543210').replace(/[^0-9]/g, '');
    if (cleanPhone.length === 10) cleanPhone = '91' + cleanPhone;
    window.open(`https://wa.me/${cleanPhone}?text=${text}`, '_blank');
    if (typeof showNotification === 'function') {
      showNotification(`Follow-up appointment reminder prepared for WhatsApp (+${cleanPhone})!`, 'success');
    }
  }

  // =========================================================================
  // AMBIENT CLINICAL SCRIBE (DICTATE RX)
  // =========================================================================

  function dictateRx() {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
      if (typeof showNotification === 'function') {
        showNotification('Voice dictation active in simulation mode: Dictate diagnosis & notes.', 'info');
      }
      const diagInput = document.getElementById('fast-diagnosis-input');
      if (diagInput) {
        diagInput.value = diagInput.value + ' [Voice Dictated: Subacute joint arthralgia with morning stiffness, pulse Batee, humor Balgham predominate]';
        calculateIlajBilZidd();
      }
      return;
    }
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-IN';
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    if (typeof showNotification === 'function') {
      showNotification('🎤 Listening... Speak diagnosis, symptoms, or notes now.', 'info');
    }

    recognition.onresult = function(event) {
      const transcript = event.results[0][0].transcript;
      const diagInput = document.getElementById('fast-diagnosis-input');
      if (diagInput) {
        diagInput.value = (diagInput.value ? diagInput.value + ' ' : '') + transcript;
        calculateIlajBilZidd();
      }
      if (typeof showNotification === 'function') {
        showNotification(`✓ Transcribed: "${transcript}"`, 'success');
      }
    };

    recognition.onerror = function() {
      if (typeof showNotification === 'function') {
        showNotification('Microphone unavailable or permission denied.', 'warning');
      }
    };

    try {
      recognition.start();
    } catch(e) {
      if (typeof showNotification === 'function') {
        showNotification('Voice dictation could not be started.', 'warning');
      }
    }
  }

