  function switchLoginModalTab(tab) {
    const signinView = document.getElementById('login-credentials-view');
    const signupView = document.getElementById('doctor-signup-view');
    const forgotView = document.getElementById('forgot-password-view');
    const tabSignin = document.getElementById('tab-login-signin');
    const tabSignup = document.getElementById('tab-login-signup');

    if (forgotView) forgotView.classList.add('hidden');

    if (tab === 'signup') {
      if (signinView) signinView.classList.add('hidden');
      if (signupView) signupView.classList.remove('hidden');
      if (tabSignup) {
        tabSignup.className = "flex-1 py-2 px-3 rounded-xl font-bold transition flex items-center justify-center gap-1.5 bg-emerald-600 text-white shadow cursor-pointer";
      }
      if (tabSignin) {
        tabSignin.className = "flex-1 py-2 px-3 rounded-xl font-bold transition flex items-center justify-center gap-1.5 text-slate-300 hover:text-white hover:bg-slate-800 cursor-pointer";
      }
    } else {
      if (signupView) signupView.classList.add('hidden');
      if (signinView) signinView.classList.remove('hidden');
      if (tabSignin) {
        tabSignin.className = "flex-1 py-2 px-3 rounded-xl font-bold transition flex items-center justify-center gap-1.5 bg-emerald-600 text-white shadow cursor-pointer";
      }
      if (tabSignup) {
        tabSignup.className = "flex-1 py-2 px-3 rounded-xl font-bold transition flex items-center justify-center gap-1.5 text-slate-300 hover:text-white hover:bg-slate-800 cursor-pointer";
      }
    }
  }

  function togglePasswordVisibility(inputId, iconId) {
    const input = document.getElementById(inputId);
    const icon = document.getElementById(iconId);
    if (!input) return;
    if (input.type === 'password') {
      input.type = 'text';
      if (icon) icon.textContent = '🙈';
    } else {
      input.type = 'password';
      if (icon) icon.textContent = '👁️';
    }
  }

  function selectSignupRole(role) {
    const validRoles = ['doctor', 'pharmacy', 'clinic', 'nurse'];
    const activeRole = validRoles.includes(role) ? role : 'doctor';

    const hiddenRoleInput = document.getElementById('staff-signup-role');
    if (hiddenRoleInput) hiddenRoleInput.value = activeRole;

    // Toggle button styles
    validRoles.forEach(r => {
      const btn = document.getElementById('role-btn-' + r);
      if (btn) {
        if (r === activeRole) {
          if (r === 'doctor') {
            btn.className = 'p-2 rounded-xl text-center font-bold text-xs transition border cursor-pointer bg-emerald-600 text-white border-emerald-500 shadow-sm';
          } else if (r === 'pharmacy') {
            btn.className = 'p-2 rounded-xl text-center font-bold text-xs transition border cursor-pointer bg-amber-600 text-white border-amber-500 shadow-sm';
          } else if (r === 'clinic') {
            btn.className = 'p-2 rounded-xl text-center font-bold text-xs transition border cursor-pointer bg-blue-600 text-white border-blue-500 shadow-sm';
          } else if (r === 'nurse') {
            btn.className = 'p-2 rounded-xl text-center font-bold text-xs transition border cursor-pointer bg-teal-600 text-white border-teal-500 shadow-sm';
          }
        } else {
          btn.className = 'p-2 rounded-xl text-center font-bold text-xs transition border cursor-pointer bg-slate-950 text-slate-300 border-slate-800 hover:border-slate-700 hover:text-white';
        }
      }

      // Toggle field sections
      const fieldSec = document.getElementById('signup-fields-' + r);
      if (fieldSec) {
        if (r === activeRole) {
          fieldSec.classList.remove('hidden');
        } else {
          fieldSec.classList.add('hidden');
        }
      }
    });

    // Update Role Badge and Submit button
    const badge = document.getElementById('signup-role-badge');
    const submitBtn = document.getElementById('doc-signup-submit-btn');
    if (activeRole === 'doctor') {
      if (badge) {
        badge.textContent = 'DOCTOR / HAKEEM (طبیب)';
        badge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-950 text-emerald-400 border border-emerald-500/40 font-mono';
      }
      if (submitBtn) submitBtn.textContent = 'Create My Matab Account (طبیب اکاؤنٹ بنائیں) →';
    } else if (activeRole === 'pharmacy') {
      if (badge) {
        badge.textContent = 'PHARMACIST / DISPENSARY (دوا ساز)';
        badge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-950 text-amber-400 border border-amber-500/40 font-mono';
      }
      if (submitBtn) submitBtn.textContent = 'Register Pharmacy & Dispensary Account →';
    } else if (activeRole === 'clinic') {
      if (badge) {
        badge.textContent = 'RECEPTION / OPD DESK (استقبالیہ)';
        badge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-blue-950 text-blue-400 border border-blue-500/40 font-mono';
      }
      if (submitBtn) submitBtn.textContent = 'Register Reception Desk Account →';
    } else if (activeRole === 'nurse') {
      if (badge) {
        badge.textContent = 'NURSE / TRIAGE (نرسنگ ڈیسک)';
        badge.className = 'text-[10px] font-bold px-2 py-0.5 rounded-full bg-teal-950 text-teal-400 border border-teal-500/40 font-mono';
      }
      if (submitBtn) submitBtn.textContent = 'Register Nursing Station Account →';
    }
  }

