  async function handleDoctorSignup(e) {
    if (e && e.preventDefault) e.preventDefault();
    const role = (document.getElementById('staff-signup-role')?.value || 'doctor').toLowerCase();
    const name = (document.getElementById('doc-signup-name')?.value || '').trim();
    const email = (document.getElementById('doc-signup-email')?.value || '').trim().toLowerCase();
    const phone = (document.getElementById('doc-signup-phone')?.value || '').trim();
    const password = document.getElementById('doc-signup-password')?.value || '';
    const errBox = document.getElementById('doctor-signup-error');
    const submitBtn = document.getElementById('doc-signup-submit-btn');

    if (!name || !email || !password) {
      if (errBox) {
        errBox.textContent = 'Please fill all required profile fields: Name, Email, and Password.';
        errBox.classList.remove('hidden');
      }
      return;
    }

    if (password.length < 4) {
      if (errBox) {
        errBox.textContent = 'Password must be at least 4 characters.';
        errBox.classList.remove('hidden');
      }
      return;
    }

    let title = '';
    let facilityId = 'FAC-CLINIC-01';

    if (role === 'doctor') {
      const degree = (document.getElementById('doc-signup-degree')?.value || '').trim();
      const reg = (document.getElementById('doc-signup-reg')?.value || '').trim();
      const clinicName = (document.getElementById('doc-signup-clinic-name')?.value || '').trim();
      const clinicUrdu = (document.getElementById('doc-signup-clinic-urdu')?.value || '').trim();
      const timing = (document.getElementById('doc-signup-timing')?.value || '').trim();
      const address = (document.getElementById('doc-signup-address')?.value || '').trim();

      title = degree || 'Senior Tabeeb (NCISM-BUMS)';
      facilityId = 'FAC-DOC-' + Math.random().toString(36).substring(2, 8).toUpperCase();

      // Auto-configure the Doctor's personalized Clinic Letterhead & Stamp
      const newLetterhead = {
        clinicName: clinicName || 'ZAYVORA INTEGRATIVE CLINICAL MATAB',
        clinicUrdu: clinicUrdu || 'مطب زیورا فار ہربل میڈیسن والطب یونانی',
        doctorName: name,
        doctorDegree: title,
        doctorReg: reg || 'NCISM/REG/2026',
        clinicTiming: timing || 'OPD Timing: 10:00 AM - 02:00 PM',
        clinicAddress: address || 'ZAYVORA Integrative Healthcare & Research Centre'
      };
      try {
        localStorage.setItem('zayvora_clinic_letterhead_settings', JSON.stringify(newLetterhead));
      } catch (e) {}
      if (typeof applyLetterheadToPrescriptionSlip === 'function') {
        applyLetterheadToPrescriptionSlip(newLetterhead);
      }
    } else if (role === 'pharmacy') {
      const drugLic = (document.getElementById('staff-signup-drug-license')?.value || '').trim();
      title = `Pharmacist (${drugLic || 'Reg. Dispensary'})`;
      facilityId = 'FAC-PHARM-' + Math.random().toString(36).substring(2, 8).toUpperCase();
    } else if (role === 'clinic') {
      const desk = (document.getElementById('staff-signup-clinic-desk')?.value || '').trim();
      title = desk ? `OPD Reception (${desk})` : 'Patient Intake & Reception Desk';
      facilityId = 'FAC-CLINIC-' + Math.random().toString(36).substring(2, 8).toUpperCase();
    } else if (role === 'nurse') {
      const ward = (document.getElementById('staff-signup-nurse-ward')?.value || '').trim();
      title = `Registered Nurse (${ward || 'Tadbeer & Triage'})`;
      facilityId = 'FAC-WARD-' + Math.random().toString(36).substring(2, 8).toUpperCase();
    }

    if (submitBtn) {
      submitBtn.textContent = 'Registering Account...';
      submitBtn.disabled = true;
    }

    // Call backend registration or graceful local authorization
    let token = null;
    try {
      if (typeof apiFetch === 'function') {
        const res = await apiFetch('/api/v1/auth/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            email: email,
            password: password,
            fullName: name,
            phone: phone,
            role: role.toUpperCase(),
            facilityId: facilityId
          })
        });
        const data = await res.json().catch(() => ({}));
        if (res.ok && data.ok) {
          token = data.token || data.access_token;
        }
      }
    } catch (err) {
      // Offline fallback
    }

    if (!token) {
      const errBox = document.getElementById('doctor-signup-error');
      if (errBox) {
        errBox.textContent = 'Registration failed or backend server is unreachable. Please verify server status.';
        errBox.classList.remove('hidden');
      }
      if (submitBtn) {
        submitBtn.textContent = 'Complete Registration →';
        submitBtn.disabled = false;
      }
      return;
    }

    state.currentUser = {
      email: email,
      name: name,
      title: title,
      role: role,
      isSuperAdmin: false,
      token: token,
      facilityId: facilityId
    };

    try {
      localStorage.setItem('zayvora_token', token);
      localStorage.setItem('zayvora_user', JSON.stringify(state.currentUser));
    } catch (e) {}

    closeDoctorSignupModal();
    if (typeof updateAuthHeaderUI === 'function') updateAuthHeaderUI();
    if (role === 'doctor' && typeof setConsultationMode === 'function') setConsultationMode('fast');
    if (typeof switchRole === 'function') switchRole(role, true);

    if (submitBtn) {
      submitBtn.textContent = 'Create Account →';
      submitBtn.disabled = false;
    }

    if (typeof showNotification === 'function') {
      const roleLabels = {
        doctor: 'Doctor / Matab',
        pharmacy: 'Pharmacy & Dispensary',
        clinic: 'Reception & Intake Desk',
        nurse: 'Nursing Station'
      };
      showNotification(`Welcome ${name}! Your ${roleLabels[role] || 'Staff'} workspace is now ready.`, 'success');
    }
  }

