  function filterDispensaryLookup(query) {
    const res = document.getElementById('dispensary-lookup-results');
    if (!res) return;
    const q = (query || '').toLowerCase().trim();
    const items = [
      { name: 'Sharbat Banafsha', urdu: 'شربت بنفشہ', ind: 'Upper Respiratory, Dry & Productive Cough', stock: 4, badge: 'Low Stock (4 left)' },
      { name: 'Majoon Suranjan', urdu: 'معجون سرنجان', ind: 'Waja-ul-Mafasil (Rheumatoid / Gout Arthritis)', stock: 48, badge: 'In Stock (48 units)' },
      { name: 'Roghan Baiza Murgh', urdu: 'روغن بیضہ مرغ', ind: 'Alopecia, Hair Follicle Regeneration & Scalp Tonic', stock: 32, badge: 'In Stock (32 units)' },
      { name: 'Khamira Marwareed', urdu: 'خمیرہ مروارید', ind: 'Khafqan (Palpitation), Cardioprotective & Vitality', stock: 26, badge: 'In Stock (26 units)' },
      { name: 'Majoon Ushba', urdu: 'معجون عشبہ', ind: 'Musaffi-e-Dam (Blood Purifier) & Chronic Eczema', stock: 2, badge: 'Low Stock (2 left)' },
      { name: 'Habbe Jadwar', urdu: 'حب جدوار', ind: 'Muqawwi-e-Aasab (Nerve Tonic) & Chronic Fatigue', stock: 6, badge: 'Low Stock (6 left)' },
      { name: 'Itrifal Kishneezi', urdu: 'اطریفل کشنیزی', ind: 'Su-e-Hazm (Dyspepsia) & Chronic Cephalea / Gas', stock: 7, badge: 'Low Stock (7 left)' },
      { name: 'Sharbat Anar Shirin', urdu: 'شربت انار شیریں', ind: 'Gastric Hyperacidity, Bile Normalization & Liver Tonic', stock: 54, badge: 'In Stock (54 units)' },
      { name: 'Majoon Falasfa', urdu: 'معجون فلاسفہ', ind: 'Renal Function, Lumbar Pain & Geriatric Vitality', stock: 38, badge: 'In Stock (38 units)' }
    ];

    const filtered = q ? items.filter(i => i.name.toLowerCase().includes(q) || i.urdu.includes(q) || i.ind.toLowerCase().includes(q)) : items;

    if (filtered.length === 0) {
      res.innerHTML = `<div class="p-4 text-center text-slate-500 text-xs">No formulations found matching "${q}". Check spelling or consult clinic pharmacist.</div>`;
      return;
    }

    res.innerHTML = filtered.map(i => {
      const isLow = i.stock < 10;
      return `
        <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 hover:border-slate-700 flex justify-between items-center transition">
          <div>
            <div class="flex items-center gap-1.5">
              <strong class="text-white font-bold text-xs">${i.name}</strong>
              <span class="text-emerald-400 font-serif text-[11px]" dir="rtl">${i.urdu}</span>
            </div>
            <span class="text-[10px] text-slate-400 block">${i.ind}</span>
          </div>
          <span class="text-[10px] font-mono font-bold px-2 py-0.5 rounded ${isLow ? 'bg-rose-950/70 text-rose-300 border border-rose-500/40' : 'bg-emerald-950/70 text-emerald-300 border border-emerald-500/40'}">
            ${i.badge}
          </span>
        </div>
      `;
    }).join('');
  }

