      try {
        if (window.history && window.history.pushState) {
          window.history.pushState(null, null, '#' + pageKey);
        } else {
          window.location.hash = pageKey;
        }
      } catch (e) {}
      renderNavigation();
      renderWorkspace();
      window.scrollTo({ top: 0, behavior: 'smooth' });
