    function calculateDetailedMizaj() {
      const ans = window.previewMizajAnswers || { temp: 'cold', moisture: 'moist', physique: 'broad', digestion: 'sluggish', sleep: 'deep', disposition: 'calm' };
      let d = 0, s = 0, b = 0, sa = 0;
      
      // 1. Thermal Sensitivity
      if (ans.temp === 'hot') { d += 30; s += 30; }
      else { b += 30; sa += 30; }

      // 2. Moisture & Texture
      if (ans.moisture === 'moist') { d += 30; b += 30; }
      else { s += 30; sa += 30; }

      // 3. Frame / Physique
      if (ans.physique === 'broad') d += 20;
      else if (ans.physique === 'athletic') s += 20;
      else if (ans.physique === 'soft') b += 20;
      else if (ans.physique === 'slender') sa += 20;

      // 4. Digestion
      if (ans.digestion === 'regular') d += 15;
      else if (ans.digestion === 'sharp') s += 15;
      else if (ans.digestion === 'sluggish') b += 15;
      else if (ans.digestion === 'variable') sa += 15;

      // 5. Sleep Pattern
      if (ans.sleep === 'moderate') d += 15;
      else if (ans.sleep === 'light') s += 15;
      else if (ans.sleep === 'deep') b += 15;
      else if (ans.sleep === 'disturbed') sa += 15;

      // 6. Emotional Disposition
      if (ans.disposition === 'bold') d += 15;
      else if (ans.disposition === 'intense') s += 15;
      else if (ans.disposition === 'calm') b += 15;
      else if (ans.disposition === 'analytical') sa += 15;

      const total = d + s + b + sa || 1;
      const dPct = Math.round((d / total) * 100);
      const sPct = Math.round((s / total) * 100);
      const bPct = Math.round((b / total) * 100);
      const saPct = Math.max(0, 100 - (dPct + sPct + bPct));

      const ranked = [
        { key: "Damawi", pct: dPct },
        { key: "Safrawi", pct: sPct },
        { key: "Balghami", pct: bPct },
        { key: "Sawdawi", pct: saPct }
      ].sort((x, y) => y.pct - x.pct);

      const dominant = ranked[0].key;
      const secondary = ranked[1].key;

      const archetypeMap = {
        Damawi: {
          title: "Damawi (Sanguine / خلط دم) — Har-Tar",
          diet: "Moderate protein, barley, fresh vegetables, pomegranate, and coriander. Strictly reduce excessive red meat, sweet dates, and heavy rich curries.",
          favourable: "Barley water, pomegranate, seasonal green herbs, amla, cucumber, mint tea.",
          avoid: "Heavy red meat, excessive deep-fried snacks, rich sweets, dry hot spices."
        },
        Safrawi: {
          title: "Safrawi (Bilious / خلط صفراء) — Har-Yabis",
          diet: "Cooling & soothing diet (Barid-Tar). Tamarind, cucumber, melon, milk, ispaghol, and rose water. Strictly avoid deep-fried, dry-hot chillies, and mustard.",
          favourable: "Sharbat Bazoori, fresh cucumber, watermelon, ispaghol husk, mint, coconut water.",
          avoid: "Red chillies, excess raw garlic, fried pakoras, mustard oil, dry spicy curries."
        },
        Balghami: {
          title: "Balghami (Phlegmatic / خلط بلغم) — Barid-Tar",
          diet: "Warming & digestive drying regimen (Har-Yabis). Honey, walnuts, ginger, black pepper, and fenugreek. Strictly avoid iced drinks, curds, white rice, and heavy dairy.",
          favourable: "Warm honey water, ginger tea, walnuts, dry dates, garlic, black pepper.",
          avoid: "Chilled water, heavy yogurt (dahi), cold milk, ice creams, excess white rice."
        },
        Sawdawi: {
          title: "Sawdawi (Melancholic / خلط سوداء) — Barid-Yabis",
          diet: "Moistening & warm nourishing regimen (Har-Tar). Almonds, warm goat milk, bone broth, figs, and raisins. Strictly avoid stale food, brinjal (baingan), beef, and lentils.",
          favourable: "Almond milk, soaked figs, mutton soup, raisins, olive oil, warm herbal broths.",
          avoid: "Stale leftovers, brinjal (baingan), beef, dry lentils (urad/masoor), pickles."
        }
      };

      const info = archetypeMap[dominant] || archetypeMap.Damawi;

      return {
        title: info.title,
        primary: dominant,
        dominant: dominant,
        secondary: secondary,
        percentages: { 
          Damawi: dPct, Safrawi: sPct, Balghami: bPct, Sawdawi: saPct,
          damawi: dPct, safrawi: sPct, balghami: bPct, sawdawi: saPct
        },
        dietaryDirective: info.diet,
        favourableFoods: info.favourable,
        avoidFoods: info.avoid
      };
    }

