    // Keyboard Shortcuts (⌘K for Search, ⌘N for Walk-In, ⌘P for Print, Escape to Close)
    window.addEventListener('keydown', (e) => {
      if ((e.metaKey || e.ctrlKey) && (e.key === 'k' || e.key === 'K')) {
        e.preventDefault();
        toggleSearchModal();
      }
      if ((e.metaKey || e.ctrlKey) && (e.key === 'n' || e.key === 'N')) {
        e.preventDefault();
        if (typeof window.scrollToOpdBooking === 'function') {
          window.scrollToOpdBooking();
        }
      }
      if ((e.metaKey || e.ctrlKey) && (e.key === 'p' || e.key === 'P')) {
        const rxModal = document.getElementById('bilingual-rx-slip-modal');
        if (rxModal && !rxModal.classList.contains('hidden')) {
          e.preventDefault();
          window.print();
        }
      }
      if (e.key === 'Escape') {
        // Universal modal closer: close all active/visible modals on ESC
        document.querySelectorAll('[id$="-modal"]').forEach(m => {
          if (m && !m.classList.contains('hidden')) m.classList.add('hidden');
        });
        const explainM = document.getElementById('explain-my-health-modal');
        if (explainM) explainM.remove();
        const docM = document.getElementById('medical-doctrine-modal');
        if (docM) docM.remove();
        const facM = document.getElementById('onboard-facility-modal');
        if (facM) facM.remove();
        if (typeof toggleLoginModal === 'function') toggleLoginModal(false);
      }
    });

    // Live Clinical CDSS Telemetry & Offline Readiness Inspector
    async function checkLiveAiStatus(showAlert) {
      const badge = document.getElementById('live-ai-badge');
      const dot = document.getElementById('live-ai-dot');
      const text = document.getElementById('live-ai-text');
      try {
        const res = await apiFetch('/api/v1/ai/status');
        if (res.ok) {
          const data = await res.json();
          if (badge) {
            // Strictly hide CDSS badge on public website / patient view!
            const allowedRoles = ['doctor', 'research', 'manufacturing', 'admin'];
            if (typeof state !== 'undefined' && allowedRoles.includes(state.role)) {
              badge.classList.remove('hidden');
              badge.classList.add('flex');
            } else {
              badge.classList.add('hidden');
              badge.classList.remove('flex');
            }
            if (data.is_cloud_connected) {
              if (dot) dot.className = "w-2 h-2 rounded-full bg-emerald-400 animate-pulse";
              if (text) {
                text.textContent = data.providers?.gemini ? "CDSS: ACTIVE" : "CDSS: CLOUD";
                text.className = "text-[9px] font-bold text-emerald-300 font-mono hidden lg:inline";
              }
              badge.title = `Clinical Decision Support: ${data.active_tier} (Cloud Connected)`;
            } else {
              if (dot) dot.className = "w-2 h-2 rounded-full bg-amber-400";
              if (text) {
                text.textContent = "CDSS: LOCAL";
                text.className = "text-[9px] font-bold text-amber-300 font-mono hidden lg:inline";
              }
              badge.title = "Clinical Decision Support: Standalone Deterministic Pharmacopoeia Engine (Offline Ready)";
            }
          }
          if (showAlert) {
            showNotification(`CDSS Telemetry: Active Knowledge Layer: ${data.active_tier} | Mode: ${data.is_cloud_connected ? 'Cloud Verified' : 'Local Standalone'} | DB: ${(data.database_backend || 'sqlite').toUpperCase()}`, 'info');
          }
        }
      } catch (e) {
        if (badge) {
          const allowedRoles = ['doctor', 'research', 'manufacturing', 'admin'];
          if (typeof state !== 'undefined' && allowedRoles.includes(state.role)) {
            badge.classList.remove('hidden');
            badge.classList.add('flex');
          } else {
            badge.classList.add('hidden');
            badge.classList.remove('flex');
          }
          if (dot) dot.className = "w-2 h-2 rounded-full bg-amber-400";
          if (text) text.textContent = "CDSS: LOCAL";
        }
      }
    }
    window.checkLiveAiStatus = checkLiveAiStatus;

