                name: `${liveFirst.first_name || ''} ${liveFirst.last_name || ''}`.trim() || 'Hamza Farooqi',
                age: liveFirst.age || 44,
                gender: liveFirst.gender || 'Male',
                phone: liveFirst.contact_phone || '+91-9876543210',
