        'care_journey': 'care_journey',
        'clinics': 'clinics',
        'doctors': 'doctors',
        'team': 'team',
        'knowledge': 'knowledge',
        'faqs': 'faqs',
        'faq': 'faqs',
        'contact': 'contact',
        'privacy': 'privacy',
        'privacy-policy': 'privacy',
        'terms': 'terms',
        'terms-and-conditions': 'terms',
        'disclaimer': 'disclaimer',
        'shipping': 'shipping',
