    function sendTokenViaWhatsApp(token, patient, phone) {
      const pName = patient || (state.patient && state.patient.name) || 'Valued Patient';
      const cleanPhone = (phone || (state.patient && state.patient.phone) || '').replace(/[^0-9]/g, '');
      const todayStr = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
      
      let text = `*🌿 ZAYVORA CLINICAL MATAB — APPOINTMENT TOKEN*%0A%0A`;
      text += `Assalam-o-Alaikum / Namaste *${pName}*,%0A%0A`;
      text += `Aapka OPD consultation token confirm ho gaya hai:%0A`;
      text += `🎫 *Token Number:* *#${token || 'T-104'}*%0A`;
      text += `📅 *Date:* ${todayStr}%0A`;
      text += `🩺 *Attending Doctor:* Hakeem Dr. Irfan Ashraf (BUMS, AKTC AMU)%0A`;
      text += `🏥 *Chamber:* Room 204, OPD Central Wing%0A`;
      text += `📋 *Hospital Helpline:* +91 97738 82657%0A%0A`;
      text += `_Kripya clinic screen par apna token number display hone par room mein dakhil hon._%0A`;
      text += `Shukriya! 🌿 *ZAYVORA Health OS™*`;

      const url = cleanPhone ? `https://wa.me/${cleanPhone}?text=${text}` : `https://wa.me/?text=${text}`;
      window.open(url, '_blank');
      showNotification(`Sent Token #${token} to ${pName} via WhatsApp!`, 'success');
    }
    window.sendTokenViaWhatsApp = sendTokenViaWhatsApp;

